package export_ohrats_rc_transport_provider

import (
	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/ohrats_rc_transport_types"
)

func PlanAttempts(_transport string, _iceServers []ohrats_rc_transport_types.IceServer) witTypes.Result[[]ohrats_rc_transport_types.Attempt, string] {
	return witTypes.Ok[[]ohrats_rc_transport_types.Attempt, string](
		[]ohrats_rc_transport_types.Attempt{
			{
				Mode:             ohrats_rc_transport_types.IceMode_Relay,
				Route:            ohrats_rc_transport_types.RouteClass_TurnRelay,
				GatherTimeoutMs:  25,
				ConnectTimeoutMs: 50,
				RetryDelayMs:     0,
			},
		},
	)
}

func PlanAnswer(transport string, request ohrats_rc_transport_types.AnswerRequest) witTypes.Result[ohrats_rc_transport_types.AnswerPlan, string] {
	if transport != "webrtc" {
		return witTypes.Err[ohrats_rc_transport_types.AnswerPlan, string]("unsupported transport")
	}
	return witTypes.Ok[ohrats_rc_transport_types.AnswerPlan, string](
		ohrats_rc_transport_types.AnswerPlan{
			IceServers:       request.IceServers,
			GatherTimeoutMs:  100,
			ConnectTimeoutMs: 100,
		},
	)
}
